/**
 * Authored lobe sets per site for the generated families (DECISION §11 fallback: "authored delta lobes per site",
 * "authored lobes for the sites that fail"): pre-excitation by accessory-pathway site and ectopic ventricular beats by
 * origin. Sites without an entry are generated by `frontsynth.ts` once its family scale is calibrated (synth-rhythm);
 * until then `compose.ts` rejects them with a clear error.
 *
 * Pre-excited sets are relative to the delta onset and contain the AV-nodal (fused) part at the fixed offset of the
 * catalogue scenario (`nodalOffsetMs` = AV-nodal QRS onset − delta onset). Ectopic sets are relative to the earliest
 * ventricular activation of the ectopic beat.
 */
import type { LobeSpec, PathwaySite, VentOrigin } from '../../api';
import { faceOf } from '../../heart/activation';
import { lobe, type PatternDef } from './types';

export interface PreexcitedDef extends PatternDef {
  readonly pathway: PathwaySite;
  /** AV-nodal QRS onset − delta onset (ms) the fused lobes were authored for */
  readonly nodalOffsetMs: number;
}

export interface EctopicDef extends PatternDef {
  readonly origin: VentOrigin;
}

/**
 * Left lateral accessory pathway (WPW type A). Delta: slow, low force pointing away from the left lateral base
 * (rightward, anterior, inferior) → negative/isoelectric delta in I, aVL, V5–V6, positive in V1 and the inferior leads;
 * then the steep body of the QRS as the pre-excited LV free wall and the AV-nodal front fuse.
 * Provenance: prototype B WPW_QRS re-aimed per the judges (DECISION §12.2: two-phase QRS, negative lateral delta).
 */
export const WPW_LEFT_LATERAL: PreexcitedDef = {
  id: 'preexcited:left-lateral',
  pathway: 'left-lateral',
  nodalOffsetMs: 58,
  blocks: {},
  activation: { extra: [{ face: faceOf('lv-basal-anterolateral', 1), t: -58, h: 8 }] },
  provenance: 'prototype B WPW_QRS, re-aimed (judge fixes); region timing: pathway insertion 58 ms before the Purkinje exits',
  lobes: [
    lobe('delta: pre-excited LV lateral base', 0, 40, 75, [-0.3, 0.6, -0.74], 0.55, [['lv-basal-anterolateral', 1], ['lv-basal-inferolateral', 1]]),
    lobe('pre-excited LV (anterior spread)', 30, 68, 100, [0.05, 0.5, -0.86], 1.1, [
      ['lv-mid-anterolateral', 1], ['lv-mid-inferolateral', 1], ['lv-basal-anterior', 1], ['lv-basal-inferior', 1], ['lv-apical-lateral', 0.5],
    ]),
    lobe('AV-nodal: septum + LV free wall', 52, 84, 114, [0.66, 0.5, 0.33], 1.05, [
      ['lv-mid-anteroseptal', 1], ['lv-mid-inferoseptal', 1], ['lv-apical-septal', 1], ['lv-mid-anterior', 1], ['lv-apical-anterior', 1],
      ['lv-mid-inferior', 1], ['lv-apical-inferior', 1], ['lv-apex', 1], ['rv-mid', 1], ['rv-apical', 1],
    ]),
    lobe('terminal RVOT', 86, 106, 124, [-0.4, -0.75, 0.35], 0.25, [['rv-outflow', 1], ['rv-basal', 1]]),
  ],
};

/**
 * Scar-related VT from the inferior LV (post-inferior-MI exit at the inferoapical wall): slow cell-to-cell exit,
 * then a wavefront through the septum to the RV, then the base / RVOT → superior axis, RBBB-like dominant R in V1–V2,
 * QS / rS in V5–V6. Provenance: prototype B VT_QRS; judge fixes (broader terminal QRS, monophasic R in V1).
 */
export const VT_LV_INFERIOR_SCAR: EctopicDef = {
  id: 'ectopic:lv-inferior-scar',
  origin: 'lv-inferior-scar',
  blocks: {},
  activation: { noPurkinje: true, extra: [{ face: faceOf('lv-apical-inferior', 0), t: 0, h: 10 }, { face: faceOf('lv-mid-inferior', 0), t: 6, h: 10 }] },
  provenance: 'prototype B VT_QRS (LV inferoapical exit); judge fixes of DECISION §12.2',
  lobes: [
    lobe('exit LV inferoapical (slow, cell to cell)', 0, 42, 78, [-0.1, -0.75, -0.65], 0.55, [['lv-apical-inferior', 1], ['lv-mid-inferior', 1], ['lv-apex', 1]]),
    lobe('LV → septum → RV wavefront', 34, 84, 128, [-0.55, -0.62, -0.56], 1.65, [
      ['lv-mid-inferoseptal', 1], ['lv-mid-anteroseptal', 1], ['lv-apical-septal', 1], ['rv-mid', 1], ['rv-apical', 1], ['lv-mid-anterior', 1],
      ['lv-apical-anterior', 1], ['lv-mid-anterolateral', 1], ['lv-mid-inferolateral', 1], ['lv-apical-lateral', 1],
    ]),
    lobe('basal / RVOT terminal', 108, 136, 162, [-0.15, -0.4, 0.9], 0.5, [
      ['lv-basal-anterior', 1], ['lv-basal-anterolateral', 1], ['rv-outflow', 1], ['rv-basal', 1],
    ]),
  ],
};

/**
 * Maximal (full) pre-excitation over a left lateral pathway — antidromic AVRT and the fully pre-excited beats of
 * pre-excited AF (relative to the delta onset; the region timing is `rhythm/fronts.ts › preexcitedInput`). Authored
 * (DECISION §11 fallback) because the generated family sums a point source at the left lateral base into a rightward
 * vector (the bulk of the heart lies to its right: generated area ≈ (−0.42, 0.63, −0.68)), which gave QS in V5–V6 —
 * against the Steurer criteria (no pre-excited tachycardia has predominantly negative V4–V6: the front enters at the
 * AV ring and sweeps base → apex toward the apical leads). Sequence: slow delta away from the lateral base
 * (rightward, anterior, inferior: negative / isoelectric I and aVL, positive V1); the LV free wall base → apex along
 * the long axis (dominant force: positive V2–V6, inferior axis); retrograde His–Purkinje engagement activates the
 * septum left → right and the RV body (rightward, anterior); the RVOT / RV base last. QRS 160 ms (maximal
 * pre-excitation 140–180 ms). The delta points mostly anterior (little inferior force) so the initial 30 ms stay slow in
 * ≥ 10 leads (the oracle's maximal-pre-excitation read) while the slurred upstroke is still seen in V1–V3. Result (oracle,
 * seeds 1–6): QRS ≈ 158 ms, axis ≈ +100°, I net ≈ −0.1, V1 R ≈ 0.8, V4 / V5 / V6 net ≈ +1.5 / +1.0 / +0.2 mV.
 */
export const FULL_PREEXCITED_LOBES: Readonly<Partial<Record<PathwaySite, readonly LobeSpec[]>>> = {
  'left-lateral': [
    lobe('delta: LV lateral base (slow, muscle)', 0, 32, 64, [-0.5, 0.2, -0.84], 0.55, [['lv-basal-anterolateral', 1], ['lv-basal-inferolateral', 1]]),
    lobe('pre-excited LV free wall, base → apex', 30, 78, 120, [0.5, 0.55, -0.67], 1.4, [
      ['lv-mid-anterolateral', 1], ['lv-mid-inferolateral', 1], ['lv-basal-anterior', 1], ['lv-basal-inferior', 1], ['lv-mid-anterior', 1],
      ['lv-mid-inferior', 1], ['lv-apical-lateral', 1], ['lv-apical-anterior', 1], ['lv-apical-inferior', 1], ['lv-apex', 1],
    ]),
    lobe('retrograde His–Purkinje: septum left → right + RV body', 80, 112, 142, [-0.45, 0.45, -0.75], 0.7, [
      ['lv-mid-anteroseptal', 1], ['lv-mid-inferoseptal', 1], ['lv-apical-septal', 1], ['lv-basal-anteroseptal', 1], ['lv-basal-inferoseptal', 1],
      ['rv-mid', 1], ['rv-apical', 1],
    ]),
    lobe('terminal RVOT / RV base', 118, 140, 160, [-0.5, -0.6, 0], 0.3, [['rv-outflow', 1], ['rv-basal', 1]]),
  ],
};

export const PREEXCITED_SITES: Readonly<Partial<Record<PathwaySite, PreexcitedDef>>> = { 'left-lateral': WPW_LEFT_LATERAL };
export const ECTOPIC_SITES: Readonly<Partial<Record<VentOrigin, EctopicDef>>> = { 'lv-inferior-scar': VT_LV_INFERIOR_SCAR };
